"""Pow(x, n) — binary exponentiation.

Squaring the base halves the exponent each round; a negative exponent is handled
by inverting once at the start.

Time: O(log n)   Space: O(1)
"""


class Solution:
    def myPow(self, x: float, n: int) -> float:
        if n < 0:
            x, n = 1 / x, -n
        result = 1.0
        while n:
            if n & 1:
                result *= x
            x *= x
            n >>= 1
        return result
